<?php require_once '../credentials.php';session_start();if(!isset($_SESSION['loggedin'])||$_SESSION['loggedin']!==true){header("Location: ../login.php");exit;}if(isset($_GET['id'])){$postId=$_GET['id'];$conn=new mysqli($dbHost,$dbUsername,$dbPassword,$dbName);if($conn->connect_error){die("Connection failed: ".$conn->connect_error);}$stmt=$conn->prepare("DELETE FROM blog_posts WHERE id = ?");$stmt->bind_param("i",$postId);if($stmt->execute()){$successMessage="Post deleted successfully. Redirecting to All Posts Page . . .";echo '<script>';echo 'setTimeout(function() { window.location.href = "allposts-not-inuse"; }, 3000);';echo '</script>';}else{$errorMessage="Failed to delete post.";}$stmt->close();$conn->close();}else{$errorMessage="Invalid post ID.";} ?><?php include '../Header.php'; ?><div class="ttm-page-title-row"><div class="ttm-bg-layer ttm-page-title-row-bg-layer"></div><div class="container"><div class="row"><div class="col-md-12 text-center"><div class="ttm-textcolor-white title-box"><div class="ttm-textcolor-white page-title-heading"><h2 class="title">Delete Post</h2></div><div class="breadcrumb-wrapper"><span><a href="/"title="Homepage"><i class="ti ti-home"></i> Home </a></span><span class="ttm-bread-sep">: : </span><span><span class="ttm-textcolor-skincolor">Delete Post</span></span></div></div></div></div></div></div><section class="error-404"><header class="text-center section-title"><h5>Delete Post</h5></header><div class="container pb-4"><div class="row"><div class="col-md-12"><?php if(!empty($errorMessage)): ?><div class="alert mt-3 alert-danger"><?php echo $errorMessage; ?></div><?php endif; ?><?php if(!empty($successMessage)): ?><div class="alert mt-3 alert-success"><?php echo $successMessage; ?></div><?php endif; ?></div></div></div></section><?php include '../footer.php'; ?>